import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`tiktok-ads`,heroTitle:`Write your TikTok ad scripts in minutes`,heroSubtitle:`Perplexity Computer researches trending hooks, writes native-style video scripts, and delivers production-ready briefs — automatically.`,inputUrlCta:`Write my scripts`,inputUrlPrefill:`Go to {url} and create a complete TikTok Ads script package. Analyze the brand, product, target audience, and value proposition. Then: (1) Research the top 20 trending hooks and formats in this product's niche on TikTok — note what's getting views and engagement right now, (2) Write 10 native-style video ad scripts, each with a different hook style (question, bold claim, before/after, UGC testimonial, POV, problem/solution, myth-busting, unboxing, comparison, day-in-the-life), (3) For each script, specify the opening hook (must land in the first 1 second), scene-by-scene breakdown with timing, text overlays with exact placement and timing, background music mood, and closing CTA, (4) Include a production brief for each script — camera angles, lighting, props, and talent direction, (5) Group scripts into 3 testing themes for structured creative testing. Deliver everything as a production package with scripts, shot lists, text overlay specs, and a testing roadmap.`,heroOverlaySteps:[`Analyzing your brand, product, and target audience on TikTok`,`Researching trending hooks and top-performing ad formats in your niche`,`Writing 10 native-style scripts with hooks, overlays, and production notes`,`Production briefs, shot lists, and testing roadmap — ready to shoot`],generatingSteps:[`Visiting {url} to understand your product, audience, and brand voice`,`Designing an agent to research trending TikTok hooks and ad formats`,`Configuring script generation with hooks, overlays, timing, and production notes`,`Setting up production briefs with shot lists and creative testing plan`],featureSectionTitle:`From URL to video scripts`,featureCardTitles:[`Connects to your creative tools`,`Scripts ready to shoot`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Canva, Google Sheets, Notion, Google Drive — Computer delivers scripts and production briefs in the formats your creative team already uses.`,`Hook-first scripts. Text overlay specs. Shot lists. Production briefs. Computer delivers a complete package your team can film immediately.`],capabilitySectionTitle:`Your creative strategist, on demand`,capabilitySectionSubtitle:`Paste your URL, get back 10 native-style TikTok ad scripts.`,capabilityCards:[{title:`Trend Research`,description:`Computer scans TikTok for trending hooks, sounds, and ad formats in your niche — so every script rides a wave that's already working.`},{title:`Script Writing`,description:`Computer writes 10 video ad scripts with hook-first openings, scene-by-scene breakdowns, text overlays, and closing CTAs — all native to TikTok.`},{title:`Production Briefs`,description:`Computer generates shot lists, camera angles, lighting notes, and talent direction for every script — so your production team can shoot without guessing.`},{title:`Creative Testing Plan`,description:`Computer groups scripts into testing themes — so you learn which hooks and formats convert best and scale the winners.`},{title:`Learns Your Brand`,description:`Computer remembers your product, audience, and past ad performance across sessions — so every batch of scripts gets more targeted.`},{title:`Trend Alerts`,description:`Computer monitors emerging TikTok trends and hooks in your niche — and alerts you when a new format is worth testing.`}]});export{t as default};
